<?php
function sale_return_post(int $sale,array $quantities,string $reason,string $request): int {
 global $pdo;domain_require('sales.approve');domain_require('inventory.edit');if(mb_strlen(trim($reason))<3||mb_strlen($reason)>500||!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))throw new InvalidArgumentException('Enter a valid return reason and request key.');
 return finance_atomic(function()use($pdo,$sale,$quantities,$reason,$request){
  $q=$pdo->prepare('SELECT * FROM sales WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$sale,shop_id()]);$s=$q->fetch();if(!$s)throw new RuntimeException('Invoice unavailable.',403);
  $hash=hash('sha256',json_encode([$sale,$quantities,$reason],JSON_THROW_ON_ERROR));$q=$pdo->prepare('SELECT id,content_hash FROM sales_returns WHERE shop_id=? AND request_key=? AND sale_id=?');$q->execute([shop_id(),$request,$sale]);$old=$q->fetch();if($old){if($old['content_hash']!==$hash)throw new InvalidArgumentException('Return request reused with different content.');return (int)$old['id'];}
  $q=$pdo->prepare("SELECT id FROM sales_returns WHERE sale_id=? AND shop_id=? AND status='posted'");$q->execute([$sale,shop_id()]);if($q->fetchColumn())throw new InvalidArgumentException('This invoice has already been fully returned.');
  $q=$pdo->prepare('SELECT * FROM sale_items WHERE sale_id=? AND shop_id=? ORDER BY stock_id,id');$q->execute([$sale,shop_id()]);$items=$q->fetchAll();if(!$items)throw new InvalidArgumentException('No invoice lines.');
  $lines=[];$total='0.00';$full=true;$costByCurrency=[];
  foreach($items as $it){$q=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) AS qty,COALESCE(SUM(total_amount),0) AS amount,COALESCE(SUM(cost_amount),0) AS cost FROM return_lines WHERE sale_item_id=? AND shop_id=?');$q->execute([$it['id'],shop_id()]);$returned=$q->fetch();$left=dec_sub($it['quantity'],$returned['qty'],3);
   $qty=$quantities?inventory_quantity($quantities[$it['id']]??0,true):$left;if(dec_units($qty,3)>dec_units($left,3))throw new InvalidArgumentException('Returned quantity exceeds the remaining sold quantity.');if(dec_units($qty,3)<dec_units($left,3))$full=false;if(dec_units($qty,3)===0)continue;
   $origCost=$it['cost_amount']??dec_mul(dec_add($it['unit_purchase_price'],$it['unit_expense'],6),$it['quantity']);$last=dec_units($qty,3)===dec_units($left,3);$amount=$last?dec_sub($it['total_price'],$returned['amount']):dec_mul(dec_div($it['total_price'],$it['quantity'],9),$qty);$cost=$last?dec_sub($origCost,$returned['cost']):dec_mul(dec_div($origCost,$it['quantity'],9),$qty);
   $q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$it['stock_id'],shop_id()]);$stock=$q->fetch();if(!$stock)throw new InvalidArgumentException('Original stock position is missing.');
   if(!empty($stock['mudaraba_id'])){$q=$pdo->prepare('SELECT * FROM mudaraba_contracts WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$stock['mudaraba_id'],shop_id()]);$contract=$q->fetch();if(!$contract||((dec_units($contract['paid_profit_to_partner'])>0||dec_units($contract['returned_capital'])>0)&&!partner_return_allowed($sale,$contract)))throw new InvalidArgumentException(__t('Review the distributed partnership return and recovery agreement first.','نخست برگشت جنسِ شریک و توافق دریافت اضافه‌پرداخت را تأیید کنید.','لومړی د شریک د ستنولو او اضافي پیسو توافق تایید کړئ.'));}
   $lines[]=[$it,$stock,$qty,$amount,$cost];$total=dec_add($total,$amount);$code=$it['cost_currency_code']?:$stock['currency_code'];$costByCurrency[$code]=dec_add($costByCurrency[$code]??0,$cost);
  }
  if(!$lines||dec_units($total)<0)throw new InvalidArgumentException('Select at least one item to return.');
  foreach($quantities as $key=>$value)if(!in_array((int)$key,array_map(fn($x)=>(int)$x['id'],$items),true)&&dec_units($value,3)!==0)throw new InvalidArgumentException('Item does not belong to this invoice.');
  $debtPart=dec_units($s['remaining_amount'])<dec_units($total)?dec_round($s['remaining_amount']):$total;$refund=dec_sub($total,$debtPart);$remaining=dec_sub($s['remaining_amount'],$debtPart);
  $pdo->prepare('INSERT INTO sales_returns (shop_id,sale_id,reason,status,created_by,request_key,total_amount,currency_code,content_hash) VALUES (?,?,?,?,?,?,?,?,?)')->execute([shop_id(),$sale,$reason,$full?'posted':'partial',auth_user()['id'],$request,$total,$s['currency_code'],$hash]);$rid=(int)$pdo->lastInsertId();
  foreach($lines as [$it,$stock,$qty,$amount,$cost]){$q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$stock['id'],shop_id()]);$stock=$q->fetch();$newQty=dec_add($stock['quantity'],$qty,3);$value=dec_add(inventory_value($stock),$cost);$pdo->prepare('UPDATE stock SET quantity=?,inventory_value=?,capital_amount=?,purchase_price=?,expenses=0 WHERE id=? AND shop_id=?')->execute([$newQty,$value,$value,dec_div($value,$newQty,6),$stock['id'],shop_id()]);$pdo->prepare('INSERT INTO return_lines (shop_id,sale_id,sale_item_id,quantity,total_amount,cost_amount,return_id) VALUES (?,?,?,?,?,?,?)')->execute([shop_id(),$sale,$it['id'],$qty,$amount,$cost,$rid]);inventory_movement((int)$stock['id'],'sales_return',$rid,$qty,$cost,$stock['currency_code']);
   if(!empty($stock['mudaraba_id'])){$known=(int)($it['profit_known']??1)===1&&($it['cost_currency_code']??$stock['currency_code'])===$s['currency_code'];$returnProfit=$known?dec_sub($amount,$cost):'0.00';$pdo->prepare('UPDATE mudaraba_contracts SET total_sales_amount=total_sales_amount-?,total_profit_amount=total_profit_amount-? WHERE id=? AND shop_id=? AND currency_code=?')->execute([$amount,$returnProfit,$stock['mudaraba_id'],shop_id(),$s['currency_code']]);$ctx=currency_context(['currency_code'=>$s['currency_code']]);$ctx['profit_known']=$known;$ctx['cost_currency']=$it['cost_currency_code']??$stock['currency_code'];currency_record('mudaraba_contracts',$stock['mudaraba_id'],$ctx,['add_sales'=>dec_mul($amount,-1),'add_profit'=>dec_mul($returnProfit,-1)],'return');}
  }
  $contracts=[];foreach($lines as [$it,$stock])if(!empty($stock['mudaraba_id']))$contracts[(int)$stock['mudaraba_id']]=true;foreach(array_keys($contracts) as $contract){partner_share_sync($contract,'return',$rid);$pdo->prepare("UPDATE mudaraba_contracts SET status='active',settlement_date=NULL WHERE id=? AND shop_id=?")->execute([$contract,shop_id()]);}
  $posted=finance_has('sale',$sale,$s['currency_code']);if(dec_units($total)>0&&!$posted&&!finance_has('legacy_sale_opening',$sale,$s['currency_code'])&&dec_units($s['remaining_amount'])>0)finance_post('legacy_sale_opening',$sale,$s['currency_code'],date('Y-m-d'),'Legacy invoice opening',[['1100',$s['remaining_amount'],0],['3900',0,$s['remaining_amount']]]);$debit=$posted?'4010':'3900';$journal=[[$debit,$total,0]];if(dec_units($debtPart)>0)$journal[]=['1100',0,$debtPart];if(dec_units($refund)>0)$journal[]=['2100',0,$refund];if(dec_units($total)>0)finance_post('sale_return',$rid,$s['currency_code'],date('Y-m-d'),'Return invoice '.$s['invoice_no'],$journal);
  foreach($costByCurrency as $code=>$cost)if(dec_units($cost)>0)finance_post('sale_return_cost',$rid,$code,date('Y-m-d'),'Returned stock cost',[['1200',$cost,0],[finance_has('sale_cost',$sale,$code)?'5000':'3900',0,$cost]]);
  if(dec_units($refund)>0)$pdo->prepare('INSERT INTO customer_refunds (shop_id,sale_id,return_id,currency_code,amount) VALUES (?,?,?,?,?)')->execute([shop_id(),$sale,$rid,$s['currency_code'],$refund]);
  $pdo->prepare('UPDATE sales SET remaining_amount=? WHERE id=? AND shop_id=?')->execute([$remaining,$sale,shop_id()]);$pdo->prepare('UPDATE debts SET remaining_amount=?,status=? WHERE sale_id=? AND shop_id=?')->execute([$remaining,dec_units($remaining)===0?'تسویه':'باز',$sale,shop_id()]);domain_audit('sales_return','sale',$sale,['return_id'=>$rid,'value'=>$total,'refund_due'=>$refund,'debt_reduction'=>$debtPart,'full'=>$full]);return $rid;
 });
}
function sale_refund_pay(int $refund,int $account,$amount,string $request,string $date): int {
 global $pdo;domain_require('treasury.approve');$amount=finance_amount($amount);return finance_atomic(function()use($pdo,$refund,$account,$amount,$request,$date){$q=$pdo->prepare('SELECT * FROM customer_refunds WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$refund,shop_id()]);$r=$q->fetch();if(!$r)throw new RuntimeException('Refund unavailable.',403);$a=funds_account($account,$r['currency_code']);$q=$pdo->prepare("SELECT id,amount,account_id FROM fund_transactions WHERE request_key=? AND shop_id=? AND source_type='refund' AND source_id=?");$q->execute([$request,shop_id(),$refund]);$old=$q->fetch();if($old){if(dec_round($old['amount'])!==$amount||(int)$old['account_id']!==$account)throw new InvalidArgumentException('Refund request content changed.');return (int)$old['id'];}if(dec_units($amount)>dec_units(dec_sub($r['amount'],$r['paid_amount'])))throw new InvalidArgumentException('Refund exceeds the outstanding amount.');$id=funds_record($account,'out',$amount,'2100','refund',$refund,$request,$date);$pdo->prepare('UPDATE customer_refunds SET paid_amount=paid_amount+? WHERE id=? AND shop_id=?')->execute([$amount,$refund,shop_id()]);return $id;});
}
/** Returned quantities and money are independent: credit the payable before creating a refund receivable. */
function purchase_return_post(int $purchase,string $reason,array $quantities=[],?string $request=null): int {
 global $pdo;domain_require('purchases.approve');domain_require('inventory.edit');$reason=trim($reason);$request=$request??bin2hex(random_bytes(16));
 if(mb_strlen($reason)<3||mb_strlen($reason)>500||!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))throw new InvalidArgumentException(__t('Enter a valid return reason and request.','دلیل معتبر برای برگشت بنویسید.','د ستنولو سم لامل ولیکئ.'));
 $normalized=[];foreach($quantities as $id=>$qty){if(!ctype_digit((string)$id)||(int)$id<1)throw new InvalidArgumentException('Invalid purchase item.');$normalized[(int)$id]=inventory_quantity($qty,true);}ksort($normalized);$hash=hash('sha256',json_encode([$purchase,$reason,$normalized],JSON_THROW_ON_ERROR));
 return finance_atomic(function()use($pdo,$purchase,$reason,$normalized,$request,$hash){
  $q=$pdo->prepare('SELECT * FROM inventory_purchases WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$purchase,shop_id()]);$p=$q->fetch();if(!$p)throw new RuntimeException(__t('Purchase unavailable.','خرید یافت نشد.','پېرود ونه موندل شو.'),403);
  $q=$pdo->prepare('SELECT id,content_hash FROM purchase_returns WHERE shop_id=? AND request_key=?');$q->execute([shop_id(),$request]);if($old=$q->fetch()){if(!hash_equals((string)$old['content_hash'],$hash))throw new InvalidArgumentException('Return request reused with different content.');return (int)$old['id'];}
  $q=$pdo->prepare('SELECT id FROM purchase_returns WHERE shop_id=? AND purchase_id=? AND full_return=1');$q->execute([shop_id(),$purchase]);if($q->fetchColumn())throw new InvalidArgumentException(__t('This purchase has already been fully returned.','این خرید قبلاً کامل برگشت شده است.','دا پېرود مخکې بشپړ ستنول شوی.'));
  if(!finance_has('purchase',$purchase,$p['currency_code'])&&!purchase_opening_reviewed($purchase))throw new InvalidArgumentException(__t('Review the legacy purchase opening balance first.','نخست ماندهٔ آغاز خرید قدیمی را بررسی کنید.','لومړی د پخواني پېرود مانده تایید کړئ.'));
  $q=$pdo->prepare('SELECT * FROM inventory_purchase_items WHERE purchase_id=? AND shop_id=? ORDER BY stock_id,id');$q->execute([$purchase,shop_id()]);$items=$q->fetchAll();if(!$items)throw new InvalidArgumentException('Purchase has no items.');
  $rows=[];$total='0.00';$cost='0.00';$full=true;$known=[];
  foreach($items as $it){$known[]=(int)$it['id'];$q=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) AS qty,COALESCE(SUM(return_value),0) AS value_amount FROM purchase_return_lines WHERE shop_id=? AND purchase_item_id=?');$q->execute([shop_id(),$it['id']]);$prior=$q->fetch();$left=dec_sub($it['quantity'],$prior['qty'],3);$qty=$normalized?($normalized[$it['id']]??'0.000'):$left;
   if(dec_units($qty,3)>dec_units($left,3))throw new InvalidArgumentException(__t('Return quantity exceeds the unreturned purchase quantity.','مقدار برگشت از باقی‌ماندهٔ خرید بیشتر است.','د ستنولو مقدار له پېرود زیات دی.'));if(dec_units($qty,3)<dec_units($left,3))$full=false;if(dec_units($qty,3)===0)continue;
   $q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$it['stock_id'],shop_id()]);$stock=$q->fetch();if(!$stock||dec_units(dec_sub($stock['quantity'],$stock['reserved_qty'],3),3)<dec_units($qty,3))throw new InvalidArgumentException(__t('Not enough unreserved stock for this return.','برای این برگشت، جنس آزاد کافی نیست.','د ستنولو لپاره ازاد توکي کافي نه دي.'));
   if(!empty($stock['partner_id']))throw new InvalidArgumentException('Review general-partner ownership separately before returning these goods.');if(!empty($stock['mudaraba_id'])){$contract=partner_contract((int)$stock['mudaraba_id'],true);if(!partner_purchase_return_allowed($purchase,$contract))throw new InvalidArgumentException(__t('Approve the partner purchase-return agreement first.','نخست توافق برگشت خرید شریک را تأیید کنید.','لومړی د شریک د پېرود ستنول تایید کړئ.'));}
   $last=dec_units($qty,3)===dec_units($left,3);$value=$last?dec_sub($it['base_total_amount'],$prior['value_amount']):dec_mul(dec_div($it['base_total_amount'],$it['quantity'],9),$qty);$lineCost=inventory_cost_for_quantity($stock,$qty);$rows[]=[$it,$qty,$value,$lineCost];$total=dec_add($total,$value);$cost=dec_add($cost,$lineCost);
  }
  foreach($normalized as $id=>$qty)if(!in_array($id,$known,true))throw new InvalidArgumentException('Item does not belong to this purchase.');if(!$rows)throw new InvalidArgumentException(__t('Choose at least one item quantity.','مقدار حداقل یک جنس را انتخاب کنید.','لږ تر لږه یو توکی وټاکئ.'));
  $balance=purchase_balance($p);$reduction=dec_units($balance['payable'])<dec_units($total)?$balance['payable']:$total;$refund=dec_sub($total,$reduction);
  $pdo->prepare('INSERT INTO purchase_returns (shop_id,purchase_id,currency_code,total_amount,reason,created_by,request_key,content_hash,full_return,cost_amount,payable_reduction,refund_receivable) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')->execute([shop_id(),$purchase,$p['currency_code'],$total,$reason,auth_user()['id'],$request,$hash,$full?1:0,$cost,$reduction,$refund]);$id=(int)$pdo->lastInsertId();
  foreach($rows as [$it,$qty,$value,$lineCost]){$q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$it['stock_id'],shop_id()]);$stock=$q->fetch();$newQty=dec_sub($stock['quantity'],$qty,3);$newValue=dec_sub(inventory_value($stock),$lineCost);$unitCost=dec_units($newQty,3)>0?dec_div($newValue,$newQty,6):$stock['purchase_price'];$pdo->prepare('UPDATE stock SET quantity=?,inventory_value=?,capital_amount=?,purchase_price=?,expenses=0 WHERE id=? AND shop_id=?')->execute([$newQty,$newValue,$newValue,$unitCost,$stock['id'],shop_id()]);$pdo->prepare('INSERT INTO purchase_return_lines (shop_id,return_id,purchase_id,purchase_item_id,stock_id,quantity,return_value,cost_amount) VALUES (?,?,?,?,?,?,?,?)')->execute([shop_id(),$id,$purchase,$it['id'],$stock['id'],$qty,$value,$lineCost]);inventory_movement((int)$stock['id'],'purchase_return',$id,'-'.$qty,'-'.$lineCost,$stock['currency_code']);}
  foreach($rows as [$it,$qty,$value])if(!empty($it['mudaraba_id']))$pdo->prepare('UPDATE mudaraba_contracts SET capital_amount=capital_amount-? WHERE id=? AND shop_id=? AND currency_code=?')->execute([$value,$it['mudaraba_id'],shop_id(),$p['currency_code']]);
  $lines=[];if(dec_units($reduction)>0)$lines[]=['2000',$reduction,0];if(dec_units($refund)>0)$lines[]=['1300',$refund,0];if(dec_units($cost)>0)$lines[]=['1200',0,$cost];$variance=dec_sub($total,$cost);if(dec_units($variance)>0)$lines[]=['5200',0,$variance];elseif(dec_units($variance)<0)$lines[]=['5200',dec_mul($variance,-1),0];if($lines)finance_post('purchase_return',$id,$p['currency_code'],date('Y-m-d'),'Purchase return '.$p['reference'],$lines);
  domain_audit('purchase_return','purchase',$purchase,['return_id'=>$id,'return_value'=>$total,'current_cost'=>$cost,'payable_reduction'=>$reduction,'refund_receivable'=>$refund,'full'=>$full]);return $id;
 });
}
/** SQL used by every legacy sales summary; source invoices remain unchanged. */
function sale_net_sql(string $field,string $alias='sales'): string {
 if(!in_array($field,['total_amount','profit'],true)||!preg_match('/^[a-z_]+$/D',$alias))throw new InvalidArgumentException('Invalid sales expression.');
 $legacy="EXISTS(SELECT 1 FROM sales_returns lr WHERE lr.sale_id=$alias.id AND lr.shop_id=$alias.shop_id AND lr.request_key IS NULL AND lr.status='posted')";
 $sum=$field==='total_amount'?"SELECT SUM(r.total_amount) FROM sales_returns r WHERE r.sale_id=$alias.id AND r.shop_id=$alias.shop_id":"SELECT SUM(CASE WHEN si.profit_known=1 THEN rl.total_amount-rl.cost_amount ELSE 0 END) FROM return_lines rl JOIN sale_items si ON si.id=rl.sale_item_id AND si.shop_id=rl.shop_id WHERE rl.sale_id=$alias.id AND rl.shop_id=$alias.shop_id";
 return "(CASE WHEN $legacy THEN 0 ELSE $alias.$field-COALESCE(($sum),0) END)";
}
